def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    seen = set()
    components = []

    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            stack = [(r, c)]
            seen.add((r, c))
            cells = []
            while stack:
                y, x = stack.pop()
                cells.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == color and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        stack.append((ny, nx))
            r0 = min(y for y, x in cells)
            c0 = min(x for y, x in cells)
            shape = frozenset((y-r0, x-c0) for y, x in cells)
            components.append((color, cells, shape))

    # Recolor a component to the color of another object with the same shape,
    # when its color is the only other color represented by that shape.
    shape_colors = {}
    for color, cells, shape in components:
        shape_colors.setdefault(shape, set()).add(color)

    for color, cells, shape in components:
        colors = shape_colors.get(shape, set())
        if len(colors) == 2 and color in colors:
            other = next(v for v in colors if v != color)
            # Use the smaller isolated matching object as the recoloring target.
            if len(cells) <= 2:
                for y, x in cells:
                    out[y][x] = other

    return out
